mapper.select:
SELECT aer.id, pap.assessment_name, p.name as patient_name, p.gender, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) as age, p.medical_record_no as medical_record_number, p.disease_type, p.enrollment_institution, aer.execution_institution, aer.status, aer.prescribing_doctor, aer.created_time, aer.updated_time FROM assessment_execution_record aer LEFT JOIN patient_assessment_plan pap ON aer.assessment_plan_id = pap.id LEFT JOIN patient p ON aer.patient_id = p.id
AND p.disease_type = #{query.diseaseType}
AND aer.status = #{query.status}
AND p.enrollment_institution = #{query.enrollmentInstitution}
AND aer.execution_institution = #{query.executionInstitution}
AND ( p.name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{query.searchKeyword}, '%') )
ORDER BY aer.created_time DESC
